export * from './orientation/types';
import { Browser } from './device-info/browser';
import { OperatingSystem } from './device-info/operating-system';
import { Network } from './network';
import { IOrientationState, OrientationValue } from './orientation/types';
import { Viewport } from './viewport';
import { VirtualKeyboard } from './virtual-keyboard';
import { PageVisibility } from './visibility';
import { Statify, Version } from '@game-studio/utilities';

export type IDeviceOrientationState = Statify<IOrientationState>;
export interface IDeviceViewportState extends Statify<Viewport> {
    /** @deprecated doesn't appear to be needed, can look at removing this once consolidation is tidier */
    notchHeight: number;
}
export type IDeviceTypeState = DeviceTypeOptions;
export type IDeviceBrowserState = Statify<Browser>;

export type IDeviceOperatingSystemState = Statify<OperatingSystem>;
export type IDeviceNetworkState = Statify<Network>;
export type IPageVisibilityState = Statify<PageVisibility>;
export type IVirtualKeyboardState = Omit<Statify<VirtualKeyboard>, 'resizesWindowWhenOpen'>;
export type IDevicePlatform = 'web' | 'app';

export interface IDeviceSystem<T extends string> {
    name: T | 'UNKNOWN';
    version: Version;
}

export interface IDeviceFeatures {
    localStorageEnabled: boolean,
    cookiesEnabled: boolean,
    supportsTouchEvents: boolean,
    supportsWebSockets: boolean,
    supportsWebGL: boolean,
    supportsHistoryApi: boolean
}

export interface IDeviceInfoState {
    platform: IDevicePlatform;
    deviceId: string;
    typeCode: string;
    type: IDeviceTypeState;
    model?: string | undefined;
    vendor?: string | undefined;
    browser: IDeviceBrowserState;
    operatingSystem: IDeviceOperatingSystemState;
    viewport: IDeviceViewportState;
    features: IDeviceFeatures;
    network: IDeviceNetworkState;
    orientation: IDeviceOrientationState;
    virtualKeyboard: IVirtualKeyboardState;
    visibility: IPageVisibilityState;
    readonly isApp: boolean;
    readonly isMobile: boolean;
    readonly isTablet: boolean;
    readonly isDesktop: boolean;
    readonly isIphoneX: boolean;
    readonly isKindle: boolean;
    readonly isFoldable: boolean;
}

export type DeviceTypeOptions = 'desktop' | 'mobile' | 'tablet';

export interface DeviceOptions {
    viewportScalar: number;
    forceType: DeviceTypeOptions;
    forceOrientation: OrientationValue;
    widthBasedOrientation: boolean;
    ignoreInversion: boolean;
    freezePageDimensions: boolean;
}

export interface IVersion {
    readonly major: number;
    readonly minor: number;
    readonly patch: number;
    readonly build: number;
}

