export type OfflineEventName =
    'up' | 'down' | 'confirmed-up'
    | 'confirmed-down' | 'checking' | 'reconnect:started'
    | 'reconnect:stopped' | 'reconnect:connecting' | 'reconnect:failure';

export interface IViewportDimensions { width: number, height: number, doubleResolution?: boolean }

export type DimensionCacheMap = Map<OrientationValue, IViewportDimensions>;

/**
 * @summary touch event has two non-standard properties across browsers that we want to include nullable type definitions for
 * @link https://developer.mozilla.org/en-US/docs/Web/API/TouchEvent
 */
export interface IExtendedTouchEvent extends TouchEvent {
    scale: number | undefined;
    rotation: number | undefined;
}

/**
 * EventEmitter Events
 */

export interface PageVisibilityEvents {
    visibilityChanged: (visibility: boolean) => void;
}

export interface NetworkEvents {
    isConnected: (isConnected: boolean) => void;
}

export interface KeyboardEvents {
    isOpen: (isOpen: boolean) => void;
    heightChanged: (height: number) => void;
}